@startuml

class Bettor {
  + name : string
  + id : int
}

class Jockey {
  + name : string
  + id : int
}

class Horse {
  + name : string
  + id : int
}

class Race {
  + id : int
  + winner : Runner
}

class Runner {
  + horse : Horse
  + jockey : Jockey
}

class Bet {
  + amount : double
  + odds : double
  + race : Race
  + runner : Runner
}

Bettor "1" -- "*" Bet : places
Jockey "0..*" -- "1" Horse : rides
Horse "1" -- "1" Jockey : riddenBy
Race "1" *-- "1..*" Runner : includes
Runner "1" -- "1" Race : participatesIn
Bet "1" -- "1" Race : forRace
Bet "1" -- "1" Runner : onRunner

@enduml

